import type { DB, UsageRecord } from './types';
import { FEATURES } from './features';
import { dayOffset } from '../lib/utils';

const usage: UsageRecord[] = [];
const usageBase = [16400, 22800, 9200, 18600, 12100, 7400];
['a-1', 'a-2', 'a-3', 'a-4', 'a-5', 'a-6'].forEach((agentId, ai) => {
  [6, 5, 4, 3, 2, 1, 0].forEach((offset, di) => {
    const tokens = Math.round(usageBase[ai] * (0.72 + ((di * 13 + ai * 7) % 40) / 100));
    usage.push({
      agentId,
      day: dayOffset(-offset),
      tokens,
      cost: Math.round(tokens * 0.000018 * 15800),
    });
  });
});

